$fpl$::jsonb) AS x(course text,code text,playlist_id text,ord integer,confidence text,level text,match text);

DO $pre$ BEGIN
 IF (SELECT count(*) FROM _p)<>97 OR (SELECT count(DISTINCT id) FROM _p)<>97 OR (SELECT count(*) FROM _pl)<>100
 OR (SELECT count(*) FROM (SELECT DISTINCT course,code FROM _pl) u)<>51
 THEN RAISE EXCEPTION 'Unexpected FACODI manifest counts'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR length(trim(channel))<2 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN('alta','média','baixa') OR ord NOT BETWEEN 1 AND 2)
 THEN RAISE EXCEPTION 'Invalid YouTube playlist metadata'; END IF;
 IF EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id WHERE p.id IS NULL)
 THEN RAISE EXCEPTION 'UC link points to an unknown playlist'; END IF;
 IF EXISTS(SELECT 1 FROM _pl t LEFT JOIN facodi.courses c ON c.code=t.course AND c.published AND c.status='active'
 LEFT JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=t.code AND u.published AND u.status='active'
 AND u.learning_object_id IS NOT NULL
 WHERE u.id IS NULL)
 THEN RAISE EXCEPTION 'Unpublished/missing academic course or UC'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.learning_objects lo JOIN _p p ON lo.source_id=p.id
 WHERE lo.id<>md5('facodi:uc-gaps-20261118:playlist:'||p.id)::uuid)
 THEN RAISE EXCEPTION 'Playlist already catalogued under another record; manual reconciliation required'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:uc-gaps-20261118:playlist:'||p.id)::uuid,'playlist',p.title,
 'facodi-uc-playlist-'||p.id,p.description,p.language,'active',true,'youtube',p.url,p.id,p.tags,
 jsonb_build_object('source_channel',p.channel,'source_channel_url',p.channel_url,'youtube_playlist_id',p.id,
 'video_count_at_verification',p.videos,'playlist_title_checked',true,'playlist_owner_verified',true,
 'owner_verification_method','youtube_oembed','items_channel_checked',true,'playlist_membership_verified',false,
 'items_automatically_imported',false,'verified_on','2026-11-18','curation_batch','facodi_uc_gap_playlists_20261118')
FROM _p p
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:uc-gaps-20261118:uc-playlist:'||u.id::text||':'||x.playlist_id)::uuid,
 u.learning_object_id,md5('facodi:uc-gaps-20261118:playlist:'||x.playlist_id)::uuid,
 'contains',91000+x.ord,'structured_catalog_import',
 jsonb_build_object('review_status','approved','review_scope','uc_programme_topic_match',
 'match_confidence',x.confidence,'content_level',x.level,'match_rationale',x.match,
 'curation_batch','facodi_uc_gap_playlists_20261118','playlist_owner_verified',true,'members_verified',false)
FROM _pl x
JOIN facodi.courses c ON c.code=x.course AND c.published AND c.status='active'
JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=x.code
ON CONFLICT DO NOTHING;

DO $post$ DECLARE n integer; links integer; BEGIN
 SELECT count(*) INTO n FROM facodi.learning_objects
 WHERE object_type='playlist' AND published AND status='active' AND metadata->>'curation_batch'='facodi_uc_gap_playlists_20261118';
 SELECT count(*) INTO links FROM _pl x
 JOIN facodi.courses c ON c.code=x.course AND c.published AND c.status='active'
 JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=x.code
 JOIN facodi.learning_object_relations r ON r.parent_object_id=u.learning_object_id
 AND r.child_object_id=md5('facodi:uc-gaps-20261118:playlist:'||x.playlist_id)::uuid AND r.relation_type='contains';
 IF n<>97 OR links<>100 THEN RAISE EXCEPTION 'UC gap playlist import not complete: playlists %, links %',n,links; END IF;
END $post$;
